CREATE TRIGGER work_items_completion_guard BEFORE UPDATE OF value ON work_items WHEN json_extract(NEW.value,'$.status')='done' AND json_extract(OLD.value,'$.status')<>'done' BEGIN
 SELECT RAISE(ABORT,'WORK_CHILD_UNFINISHED') WHERE EXISTS(SELECT 1 FROM work_items WHERE parent_id=NEW.id AND json_extract(value,'$.status') NOT IN ('done','cancelled'));
END

CREATE TRIGGER work_items_cycle_insert BEFORE INSERT ON work_items WHEN NEW.parent_id IS NOT NULL BEGIN
 SELECT RAISE(ABORT,'WORK_PARENT_CYCLE') WHERE NEW.parent_id=NEW.id OR EXISTS(WITH RECURSIVE ancestors(id,parent_id) AS (SELECT id,parent_id FROM work_items WHERE id=NEW.parent_id UNION ALL SELECT w.id,w.parent_id FROM work_items w JOIN ancestors a ON w.id=a.parent_id) SELECT 1 FROM ancestors WHERE id=NEW.id);
END

CREATE TRIGGER work_items_cycle_update BEFORE UPDATE OF parent_id ON work_items WHEN NEW.parent_id IS NOT NULL BEGIN
 SELECT RAISE(ABORT,'WORK_PARENT_CYCLE') WHERE NEW.parent_id=NEW.id OR EXISTS(WITH RECURSIVE ancestors(id,parent_id) AS (SELECT id,parent_id FROM work_items WHERE id=NEW.parent_id UNION ALL SELECT w.id,w.parent_id FROM work_items w JOIN ancestors a ON w.id=a.parent_id) SELECT 1 FROM ancestors WHERE id=NEW.id);
END

CREATE TRIGGER work_items_dependencies_insert BEFORE INSERT ON work_items BEGIN
 SELECT RAISE(ABORT,'WORK_DEPENDENCY_CYCLE') WHERE EXISTS(WITH RECURSIVE dependencies(id) AS (SELECT value FROM json_each(json_extract(NEW.value,'$.dependencyIds')) UNION SELECT d.value FROM work_items w JOIN dependencies p ON w.id=p.id JOIN json_each(json_extract(w.value,'$.dependencyIds')) d) SELECT 1 FROM dependencies WHERE id=NEW.id);
END

CREATE TRIGGER work_items_dependencies_update BEFORE UPDATE OF value ON work_items BEGIN
 SELECT RAISE(ABORT,'WORK_DEPENDENCY_CYCLE') WHERE EXISTS(WITH RECURSIVE dependencies(id) AS (SELECT value FROM json_each(json_extract(NEW.value,'$.dependencyIds')) UNION SELECT d.value FROM work_items w JOIN dependencies p ON w.id=p.id JOIN json_each(json_extract(w.value,'$.dependencyIds')) d) SELECT 1 FROM dependencies WHERE id=NEW.id);
END

CREATE TRIGGER work_items_legacy_insert AFTER INSERT ON documents WHEN NEW.namespace='shared-tasks' AND NOT EXISTS(SELECT 1 FROM work_items WHERE id=NEW.key) BEGIN
 INSERT INTO work_items(id,level,department,value,revision) VALUES(NEW.key,1,COALESCE(json_extract(NEW.value,'$.lead.team'),''),json_set(NEW.value,'$.level',1,'$.kind','task','$.workSchema',1,'$.department',COALESCE(json_extract(NEW.value,'$.lead.team'),''),'$.relatedProjectIds',json('[]'),'$.dependencyIds',json('[]'),'$.projectFields',json('{}')),COALESCE(json_extract(NEW.value,'$.version'),1));
END

CREATE TRIGGER work_items_legacy_update AFTER UPDATE OF value ON documents WHEN NEW.namespace='shared-tasks' AND COALESCE(json_extract(NEW.value,'$.version'),0)>(SELECT COALESCE(json_extract(value,'$.version'),0) FROM work_items WHERE id=NEW.key) BEGIN
 UPDATE work_items SET value=NEW.value,revision=json_extract(NEW.value,'$.version'),level=COALESCE(json_extract(NEW.value,'$.level'),1),parent_id=json_extract(NEW.value,'$.primaryParentId'),department=COALESCE(json_extract(NEW.value,'$.department'),json_extract(NEW.value,'$.lead.team'),'') WHERE id=NEW.key;
END

CREATE TRIGGER work_items_parent_open_insert BEFORE INSERT ON work_items WHEN NEW.parent_id IS NOT NULL BEGIN
 SELECT RAISE(ABORT,'WORK_PARENT_CLOSED') WHERE EXISTS(SELECT 1 FROM work_items WHERE id=NEW.parent_id AND json_extract(value,'$.status') IN ('done','cancelled'));
END

CREATE TRIGGER work_items_parent_open_move BEFORE UPDATE OF parent_id ON work_items WHEN NEW.parent_id IS NOT NULL AND NEW.parent_id IS NOT OLD.parent_id BEGIN
 SELECT RAISE(ABORT,'WORK_PARENT_CLOSED') WHERE EXISTS(SELECT 1 FROM work_items WHERE id=NEW.parent_id AND json_extract(value,'$.status') IN ('done','cancelled'));
END

CREATE TRIGGER work_items_parent_progress AFTER UPDATE OF value ON work_items WHEN NEW.parent_id IS NOT NULL AND json_extract(NEW.value,'$.status') IN ('in_progress','blocked','done') AND json_extract(NEW.value,'$.status')<>json_extract(OLD.value,'$.status') BEGIN
 UPDATE work_items SET revision=revision+1,value=json_set(value,'$.status','in_progress','$.version',json_extract(value,'$.version')+1,'$.updatedAt',json_extract(NEW.value,'$.updatedAt'),'$.history',json_insert(json_extract(value,'$.history'),'$[#]',json_object('id','activity-'||NEW.id||'-'||NEW.revision,'kind','status','actor',json_extract(NEW.value,'$.history[#-1].actor'),'at',json_extract(NEW.value,'$.updatedAt'),'from','pending','to','in_progress','text','子工作已有進展，專案進行中','mentions',json('[]'),'targets',json('[]')))) WHERE id IN (WITH RECURSIVE ancestors(id,parent_id) AS (SELECT id,parent_id FROM work_items WHERE id=NEW.parent_id UNION ALL SELECT w.id,w.parent_id FROM work_items w JOIN ancestors a ON w.id=a.parent_id) SELECT id FROM ancestors) AND json_extract(value,'$.status')='pending';
END

CREATE TRIGGER work_items_project_insert AFTER INSERT ON work_items WHEN NEW.parent_id IS NOT NULL BEGIN
 UPDATE work_items SET level=2,revision=revision+1,value=json_set(value,'$.level',2,'$.kind','project','$.version',json_extract(value,'$.version')+1,'$.updatedAt',json_extract(NEW.value,'$.updatedAt'),'$.history',json_insert(json_extract(value,'$.history'),'$[#]',json_object('id','promotion-'||NEW.id,'kind','promoted','actor',json_extract(NEW.value,'$.requester'),'at',json_extract(NEW.value,'$.updatedAt'),'text','新增第一個子工作，升級為小專案','mentions',json('[]'),'targets',json('[]')))) WHERE id=NEW.parent_id AND level=1;
END

CREATE TRIGGER work_items_project_move AFTER UPDATE OF parent_id ON work_items WHEN NEW.parent_id IS NOT NULL AND NEW.parent_id IS NOT OLD.parent_id BEGIN
 UPDATE work_items SET level=2,revision=revision+1,value=json_set(value,'$.level',2,'$.kind','project','$.version',json_extract(value,'$.version')+1,'$.updatedAt',json_extract(NEW.value,'$.updatedAt'),'$.history',json_insert(json_extract(value,'$.history'),'$[#]',json_object('id','promotion-'||NEW.id||'-'||NEW.revision,'kind','promoted','actor',json_extract(NEW.value,'$.requester'),'at',json_extract(NEW.value,'$.updatedAt'),'text','接入第一個子工作，升級為小專案','mentions',json('[]'),'targets',json('[]')))) WHERE id=NEW.parent_id AND level=1;
END

CREATE TRIGGER work_items_projection_insert AFTER INSERT ON work_items BEGIN
 INSERT INTO documents(namespace,key,value) VALUES('shared-tasks',NEW.id,NEW.value) ON CONFLICT(namespace,key) DO UPDATE SET value=excluded.value,revision=documents.revision+1;
 INSERT INTO work_notion_jobs(id,version) SELECT NEW.id,json_extract(NEW.value,'$.version') WHERE COALESCE(json_extract(NEW.value,'$.workScope'),'normal')<>'hr' ON CONFLICT(id) DO UPDATE SET version=excluded.version,next_attempt=0;
END

CREATE TRIGGER work_items_projection_update AFTER UPDATE OF value ON work_items BEGIN
 INSERT INTO documents(namespace,key,value) VALUES('shared-tasks',NEW.id,NEW.value) ON CONFLICT(namespace,key) DO UPDATE SET value=excluded.value,revision=documents.revision+1;
 INSERT INTO work_notion_jobs(id,version) SELECT NEW.id,json_extract(NEW.value,'$.version') WHERE COALESCE(json_extract(NEW.value,'$.workScope'),'normal')<>'hr' ON CONFLICT(id) DO UPDATE SET version=excluded.version,next_attempt=0;
END
